n43155.content:
\begin{definition}[Free Magma]\label{free-magma-def}\lean{FreeMagma}\leanok\uses{magma-def}
  The \emph{free magma} $M_X$ generated by a set $X$ (which we call an \emph{alphabet}) is the set of all finite formal expressions built from elements of $X$ and the operation $\diamond$.
  An element of $M_X$ will be called a \emph{word} with alphabet $X$.
  The \emph{order} of a word is the number of $\diamond$ symbols needed to generate the word.
  Thus for instance $X$ is precisely the set of words of order $0$ in $M_X$.
\end{definition}

n43156.content:
\begin{lemma} \leanok \lean{FreeMagma.elementsOfNumNodesEq_card_eq_catalan_mul_pow}
  For a finite alphabet $X$, the number of words of order $n$ is $C_n |X|^{n+1}$, where $C_n$ is the $n^{\mathrm{th}}$ Catalan number and $X$ is the cardinality of $X$.
\end{lemma}

n43157.content:
\begin{proof} \leanok
  Follows from standard properties of Catalan numbers.
\end{proof}

n43158.content:
\begin{definition}[Induced homomorphism]\label{induced-def}\uses{free-magma-def}
  Given a function $f: X \to G$ from an alphabet $X$ to a magma $G$, the \emph{induced homomorphism} $\varphi_f: M_X \to G$ is the unique extension of $f$ to a magma homomorphism.
  Similarly, if $\pi \colon X \to Y$ is a function, we write $\pi_* \colon M_X \to M_Y$ for the unique extension of $\pi$ to a magma homomorphism.
\end{definition}

n43159.content:
\begin{definition}[Law]\label{law-def}
  \lean{Law.MagmaLaw}\leanok
  \uses{induced-def}
  Let $X$ be a set. A \emph{law} with alphabet $X$ is a formal expression of the form $w \simeq w'$,
  where $w, w' \in M_X$ are words with alphabet $X$ (thus one can identify laws with alphabet $X$
  with elements of $M_X \times M_X$).
  A magma $G$ \emph{satisfies} the law $w \simeq w'$ if
  we have $\varphi_f( w ) = \varphi_f ( w' )$ for all $f: X \to G$, in which case we write
  $G \models w \simeq w'$.
\end{definition}

n43160.content:
\begin{definition}[Models]\label{models-def}
  \lean{models}\leanok
  \uses{law-def}
  A \emph{theory} is a set $\Gamma$ of laws.
  Given a theory $\Gamma$, a magma $G$ is a \emph{model} of $\Gamma$ with the
  (overloaded) notation $G\models\Gamma$ if $G\models w\simeq w'$ for every $w\simeq w'$ in $\Gamma$; we also say that $G$ \emph{satisfies} $\Gamma$.
  Given a law $E$, we write $\Gamma \models E$ if every magma $G$ that models $\Gamma$, also models $E$.
\end{definition}

n43161.content:
\begin{definition}[Derivation]\label{derivation-def}
  \lean{derive}\leanok
  \uses{law-def}
  Given a theory $\Gamma$ and a law $w\simeq w'$ over a fixed alphabet $X$, we say that
  $\Gamma$ \emph{derives} $w\simeq w'$, and write $\Gamma\vdash w\simeq w'$, if the law can
  be obtained using a finite number of applications of the following rules:
  \begin{enumerate}
    \item if $w\simeq w' \in \Gamma$, then $\Gamma\vdash w\simeq w'$.
    \item $\Gamma\vdash w\simeq w$ for any word $w$.
    \item if $\Gamma\vdash w\simeq w'$, then $\Gamma\vdash w'\simeq w$.
    \item if $\Gamma\vdash w\simeq w'$ and $\Gamma\vdash w'\simeq w''$, then $\Gamma\vdash w\simeq w''$.
    \item if $\Gamma\vdash w\simeq w'$, then $\Gamma\vdash \varphi_f(w) \simeq\varphi_f(w')$ for every $f: X \to M_X$.
    \item if $\Gamma\vdash w_1\simeq w_2$ and $\Gamma\vdash w_3\simeq w_4$, then $\Gamma\vdash w_1 \diamond w_3\simeq w_2\diamond w_4$.
  \end{enumerate}
\end{definition}

n43162.content:
\begin{theorem}[Birkhoff's completeness theorem]\label{sound-complete}\lean{Completeness}\leanok\uses{models-def, derivation-def}
  For any theory $\Gamma$ and words $w, w'$ over a fixed alphabet
  $$ \Gamma\vdash w\simeq w'\ \mathrm{iff}\ \Gamma\models w\simeq w'.$$
\end{theorem}

n43163.content:
\begin{proof}
  \leanok
  (Sketch) The `only if' component is soundness, and follows from verifying that the rules of inference in \Cref{derivation-def} holds for $\models$. The `if' part is completeness, and is proven by constructing the magma of words, quotiented out by the relation $\Gamma \vdash w \simeq w'$, which is easily seen to be an equivalence relation respecting the magma operation.
\end{proof}

n43164.content:
\begin{corollary}[Compactness theorem]\label{compactness-thm}\uses{models-def}
  Let $\Gamma$ be a theory, and let $E$ be a law.
  Then $\Gamma \models E$ if and only if there exists a finite subset $\Gamma'$ of $\Gamma$ such that $\Gamma' \models E$.
\end{corollary}

n43165.content:
\begin{proof}\uses{sound-complete}
  The claim is obvious for $\models$, and the claim then follows from \Cref{sound-complete}.
\end{proof}

n43166.content:
\begin{lemma}[Pushforward]\label{push}\uses{law-def}
  Let $w \simeq w'$ be a law with some alphabet $X$, $G$ be a magma, and $\pi: X \to Y$ be a function.
  If $G \models w \simeq w'$, then $G \models \pi_*(w) \simeq\pi_*(w')$.
  In particular, if $\pi$ is a bijection, the statements $G \models w \simeq w'$ and $G \models \pi_*(w) \simeq\pi_*(w')$ are equivalent.
\end{lemma}

n43168.content:
\begin{lemma}[Equivalence]\label{equiv}\uses{law-def}
  Let $G$ be a magma and $X$ be an alphabet.
  Then the relation $G \models w \simeq w'$ is an equivalence relation on $M_X$.
\end{lemma}

n43170.content:
\begin{lemma}[Counting laws up to relabeling]\label{law-count}\uses{push}
  Up to relabeling, the number of laws $w \simeq w'$ of total order $n$ is $C_{n+1} B_{n+2}$.
\end{lemma}

n43171.content:
\begin{proof}
  Follows from the properties of Catalan and Bell numbers.
\end{proof}

