n43232.content:
\begin{definition}[Implication]\label{impl}\uses{models-def}
  A law $E$ is said to \emph{imply} another law $E'$ if $\{E\} \models E'$, or equivalently:
  $$ G \models w  \simeq w' \implies G \models w''  \simeq w''' \hbox{ for all magmas } G$$
  Two laws are said to be \emph{equivalent} if they imply each other.
\end{definition}

n43233.content:
\begin{lemma}[Pre-order]\leanok\label{pre-order}\uses{impl}
  If we define $E \leq E'$ if $E$ implies $E'$, then this is a pre-order on the set of laws, and equivalence is an equivalence relation.
\end{lemma}

n43235.content:
\begin{lemma}[Maximal element]\label{maximal}\uses{pre-order}\lean{Law.MagmaLaw.Equation1_maximal}\leanok
  The law $0  \simeq0$ is the maximal element in this pre-order.
\end{lemma}

n43237.content:
\begin{lemma}[Minimal element]\label{minimal}\uses{pre-order}\lean{Law.MagmaLaw.Equation2_minimal}\leanok
  The law $0  \simeq1$ is the minimal element in this pre-order.
\end{lemma}

n43239.content:
\begin{lemma}[Duality of laws]\lean{Law.MagmaLaw.implies_iff_dual}\leanok\label{duality}\uses{pre-order}
  The law $w \simeq w'$ implies $w''\simeq w'''$, if and only if $w^{\mathrm{op}} \simeq(w')^{\mathrm{op}}$ implies $w''^{\mathrm{op}} \simeq(w''')^{\mathrm{op}}$.
\end{lemma}

n43240.content:
\begin{proof}
  This follows from the fact that a magma $G$ satisfies a law $w  \simeq w'$ if and only if $G^{\mathrm{op}}$ satisfies $w^{\mathrm{op}}  \simeq(w')^{\mathrm{op}}$.
\end{proof}

n43241.content:
\begin{theorem}[Diagonalization]\label{diag}
  An equational law of the form
  \begin{equation}\label{prediag}
    F(x_1,\dots,x_n) = G(y_1,\dots,y_m),
  \end{equation}
  where $x_1,\dots,x_n$ and $y_1,\dots,y_m$ are distinct elements of the alphabet, implies the diagonalized law
  $$ F(x_1,\dots,x_n) = F(x'_1,\dots,x'_n).$$
  where $x'_1,\dots,x'_n$ are distinct from $x_1,\dots,x_n$
  In particular, if $G(y_1,\dots,y_m)$ can be viewed as a specialization of $F(x'_1,\dots,x'_n)$, then these two laws are equivalent.
\end{theorem}

n43243.content:
\begin{theorem}[Laws implied by the constant law]\label{constant-impl}\uses{impl,eq46}
  If $w, w'$ each have order at least one, then the law $w \simeq w'$ is implied by the constant law (\href{https://teorth.github.io/equational_theories/implications/?46}{E46} $(\csname Equa46\endcsname)$). If exactly one of $w, w'$ has order zero, and the law $w \simeq w'$ is not implied by the constant law.
\end{theorem}

n43245.content:
\begin{theorem}[Criterion for implication]\label{variable-impl}\uses{impl}\lean{Law.MagmaLaw.SameCount.derive}\leanok
  If $w \simeq w'$ is such that every variable appears the same number of times in both $w$ and $w'$, and $w \simeq w'$ implies another law $w'' \simeq w'''$, then every variable appears the same number of times in both $w''$ and $w'''$.
\end{theorem}

n43246.content:
\begin{proof}
  Consider the magma $\mathrm{MS}$ of multisets over an arbitrary set $A$ (which can be seen as finitely supported maps $A\rightarrow \mathbb{N}$), with the multiset addition law $+$. By hypothesis, this magma satisfies $w \simeq w'$, and hence $w'' \simeq w'''$, giving the claim by comparing the orders of the elements of $A$ appearing in $w''$ and $w'''$ in this magma.
\end{proof}

n43248.content:
\begin{proof}\leanok (From \href{https://mathoverflow.net/a/450905/766}{MathOverflow}).
  By \href{https://teorth.github.io/equational_theories/implications/?387}{E387}, one has the law
\begin{equation}\label{387-again}
  (x \diamond x) \diamond y = y \diamond x.
\end{equation}
Specializing to $y=x \diamond x$, we conclude
$$(x \diamond x) \diamond(x \diamond x) = (x \diamond x) \diamond x$$
and hence by another application of \href{https://teorth.github.io/equational_theories/implications/?387}{E387} we see that $x \diamond x$ is idempotent:
\begin{equation}\label{idem}
  (x \diamond x) \diamond(x \diamond x) = x \diamond x.
\end{equation}
Now, replacing $x$ by $x \diamond x$ in \Cref{387-again} and then using \Cref{idem} we see that
$$ (x \diamond x) \diamond y = y \diamond(x \diamond x)$$
so in particular $x \diamond x$ commutes with $y \diamond y$:
\begin{equation}\label{op-idem} (x \diamond x) \diamond(y \diamond y) = (y \diamond y) \diamond(x \diamond x).
\end{equation}
Also, from two applications of \Cref{387-again} one has
$$(x \diamond x) \diamond(y \diamond y) = (y \diamond y) \diamond x = x \diamond y.$$
Thus \Cref{op-idem} simplifies to $x \diamond y = y \diamond x$, which is \href{https://teorth.github.io/equational_theories/implications/?43}{E43}.
\end{proof}

n43256.content:
\begin{proof}\leanok  The implication of \href{https://teorth.github.io/equational_theories/implications/?1689}{E1689} from \href{https://teorth.github.io/equational_theories/implications/?2}{E2} is trivial.  The converse is a surprisingly long chain of implications; see pages 326--327 of \cite{Kisielewicz2}.  With some computer assistance, we found the following human-readable proof.
We denote $y^1=y$ and $y^{n+1}=y^n\diamond y$ for $n\geq 1$.
We also introduce the notation
\begin{equation}
 f(x,y) = (x \diamond y) \diamond y , \qquad
 g(x,y) = x\diamond f(x,y) = x \diamond((x \diamond y) \diamond y) .
\end{equation}
The initial equation states $x = (y \diamond x) \diamond f(x,z)$.
Our main step will be to prove that for all $t\in M$ there exists $w\in M$ such that $f(t,w) = t$.
The rest of the proof is then straightforward.
Indeed, the initial equation gives $t = (y \diamond t) \diamond f(t,w) = (y \diamond t) \diamond t = f(y,t)$ for any $t,y\in M$.
With such a simple expression of $f$ the initial equation becomes $x = (y \diamond x) \diamond z$, which easily implies the singleton law, for instance by writing $x = ((y \diamond w) \diamond x) \diamond z = w \diamond z$ for any $w,x,y,z \in M$.

There remains to prove $f(t,w) = t$ for a well-chosen $w \in M$, explicitly, $w=g(t,t^5)=t\diamond t^7$.
For any $t,u,v \in M$, the combinations $x = f(t,u)$ and $y = v \diamond t$ satisfy $y \diamond x = t$.  Inserting these values into the initial equation yields the identity
\begin{equation}\label{Kisielewicz-tfftuz}
f(t,u) = t \diamond f(f(t,u),z) .
\end{equation}
Specialize to $z=f(u,v)$ and note that $f(t,u) \diamond z = (\cdots \diamond u) \diamond f(u,v) = u$ by the initial equation so that $f(f(t,u),z) = (f(t,u) \diamond z) \diamond z = u \diamond z = g(u,v)$.  Inserting this into \eqref{Kisielewicz-tfftuz} yields
\begin{equation}\label{Kisielewicz-ftg}
f(t,u) = t \diamond g(u,v) .
\end{equation}

On the one hand, \eqref{Kisielewicz-tfftuz} with $z=u=t$ states that $t^3 = t \diamond t^5$, so (using $f(t^n,t)=t^{n+2}$)
\begin{equation}
  f(t,t^5) = (t \diamond t^5) \diamond t^5 = t^3 \diamond t^5 = t^3 \diamond f(t^3,t) = g(t^3,t) ,
\end{equation}
and \eqref{Kisielewicz-ftg} with $(u,v)=(t^3,t)$ then implies $f(t,t^3) = t \diamond g(t^3,t) = t \diamond f(t,t^5) = g(t,t^5)$.
On the other hand, \eqref{Kisielewicz-ftg} with $(u,v)=(t,t^5)$ implies $t^3 = t \diamond g(t,t^5)$.  We deduce
\begin{equation}
  f(t,g(t,t^5)) = (t \diamond g(t,t^5)) \diamond g(t,t^5) = t^3 \diamond f(t, t^3) = (\cdots \diamond t) \diamond f(t,\dots) = t .
\end{equation}
\end{proof}

