n43353.content:
\begin{definition}[Free magma relative to a theory]\label{free-theory}\lean{FreeMagmaWithLaws}\leanok\uses{models-def}
  Let $\Gamma$ be a theory with an alphabet $X$. A \emph{free magma} with alphabet $X$ subject to the theory $\Gamma$ is a magma $M_{X,\Gamma}$ together with a function $\iota_{X,\Gamma} : X \to M_{X,\Gamma}$, with the following properties:
  \begin{description}
    \item[(i)] $M_{X,\Gamma}$ satisfies the theory $\Gamma$: $M_{X,\Gamma} \models \Gamma$.
    \item[(ii)] For any magma $M$ satisfying the theory $\Gamma$ and any function $f: X \to M$, there exists a unique magma homomorphism $\tilde{f}: M_{X,\Gamma} \to M$ such that $\tilde{f} \circ \iota_{X,\Gamma} = f$.
  \end{description}
\end{definition}

n43354.content:
\begin{theorem}[Existence and uniqueness of free magmas]\label{freemag-exist}\uses{free-theory}\lean{FreeMagma.EvalFreeMagmaWithLawsUniversalProperty}\leanok
  Let $\Gamma$ be a theory with alphabet $X$.
  \begin{description}
    \item[(i)] There exists a free magma $M_{X,\Gamma}$ with alphabet $X$ subject to the theory $\Gamma$.
    \item[(ii)] If $M_{X,\Gamma}$ and $M'_{X,\Gamma}$ are two free magmas with alphabet $X$ subject to the theory $\Gamma$, then there exists a unique magma isomorphism $\phi: M_{X,\Gamma} \to M'_{X,\Gamma}$ such that $\phi \circ \iota_{X,\Gamma} = \iota'_{X,\Gamma}$.
  \end{description}
\end{theorem}

n43358.content:
\begin{example}[Free left absorptive magma]\label{freeleft}
  Let $\Gamma$ consist of the left absorptive law (\href{https://teorth.github.io/equational_theories/implications/?4}{E4}). Then one can take $M_{X,\Gamma}$ to be $X$ with the law $x \diamond y = x$, and $\iota_{X,\Gamma}$ to be the identity map. It is easy to see that this is indeed a free magma subject to $\Gamma$.
\end{example}

n43359.content:
\begin{example}[Free constant magma]\label{freeconst}
  Let $\Gamma$ consist of the constant law (\href{https://teorth.github.io/equational_theories/implications/?46}{E46}). Then one can take $M_{X,\Gamma}$ to be the disjoint union $X \uplus \{0\}$ of $X$ and another object $0$, with $\iota_{X,\Gamma}$ being the identity embedding, and with the zero magma law $x \diamond y = 0$ for all $x,y \in X \uplus \{0\}$.
\end{example}

n43360.content:
\begin{theorem}[Canonical invariant]\label{canonical-invariant}\uses{free-theory}
  Let $\Gamma$ be a theory with some alphabet $X$, and let $M_{X,\Gamma}$ be a free magma with alphabet $X$ subject to $\Gamma$, with associated map $\iota_{X,\Gamma}: X \to M_{X,\Gamma}$. Then for any $w,w' \in M_X$, we have
  \[
  \Gamma \models w \simeq w' \text{ if and only if } \varphi_{\iota_{X,\Gamma}}(w) = \varphi_{\iota_{X,\Gamma}}(w').
  \]
\end{theorem}

n43361.content:
\begin{proof}\uses{freemag-exist}
  By \Cref{freemag-exist} we may take $M_{X,\Gamma}$ to be the canonical free magma constructed in the proof of that theorem. The claim is then clear from expanding out definitions.
\end{proof}

n43363.content:
\begin{proof}\uses{canonical-invariant}
  By \Cref{canonical-invariant}, the hypothesis $\iota_{X,\Gamma}(w) = \iota_{X,\Gamma}(w')$ is equivalent to $\Gamma \models w \simeq w'$, and the hypothesis $\iota_{X,\Gamma}(w'') \neq \iota_{X,\Gamma}(w''')$ is equivalent to $\Gamma \not \models w'' \simeq w'''$. The claim follows.
\end{proof}

n43365.content:
\begin{example}
  Let $\Gamma$ consist of the left absorption law, so we can take $M_{X,\Gamma} = X$ as in \Cref{freeleft}. Then $\varphi_{\iota_{X,\Gamma}}(w)$ is the first letter of $w$. We conclude that if $w,w'$ have the same first letter, but $w'', w'''$ do not, then $w \simeq w'$ cannot imply $w'' \simeq w'''$.
\end{example}

n43366.content:
\begin{example}
  Let $\Gamma$ consist of the constant law, so we can take $M_{X,\Gamma} = X \uplus \{0\}$ as in \Cref{freeconst}. Then $\varphi_{\iota_{X,\Gamma}}(w)$ is $x$ if $w$ is just a letter $x$ of the alphabet, and $0$ otherwise. We conclude that if $w,w', w'''$ have order at least one, but $w''$ has order zero, then $w \simeq w'$ cannot imply $w'' \simeq w'''$; this is basically \Cref{constant-impl}.
\end{example}

