n43372.content:
\begin{theorem}[Free magma of a confluent theory]\label{free-confluent}\uses{confluent-theory}
  Let $\Gamma$ be a confluent theory.  Then the free magma $M_{X,\Gamma}$ subject to this theory can be described as the space of reduced words in $M_X$ in normal form, where the operation $w \diamond_\Gamma w'$ on this magma is defined as the normal form reduction of $w \diamond w'$, and $\iota_{X,\Gamma}$ is the identity embedding (note that every single-letter word is already in normal form).
\end{theorem}

n43373.content:
\begin{proof}
  Should just be a matter of expanding definitions properly.
\end{proof}

n43374.content:
\begin{corollary}[Criterion for anti-implication]\label{confluent-anti-impl}\uses{models-def}
  Let $\Gamma$ be a confluent theory.  Then a law $w \simeq w'$ is a consequence of $\Gamma$ if and only if $w,w'$ have the same normal form reduction.  In particular, a law with this property cannot imply a law without this property.
\end{corollary}

n43378.content:
\begin{lemma}[477 lemma]\label{477-lemma}
    If $Z$ and $W$ are simple, then $Z(W\cdots(WW))$ is simple.
\end{lemma}

n43379.content:
\begin{proof}
    Assume the contrary. Then we have 2 cases.

    \textbf{Case 1: $W\cdots(WW)$ matches the pattern
    $y(x(y\cdots(yy)))$, with $k$ occurrences of $W$ ($k \le n$).}
    Since $|x(y\cdots(yy))| > n|y|$, but $|\cdots(WW)| \le (n-1)|W|$, this is impossible.

    \textbf{Case 2: $Z(W\cdots(WW))$ matches the pattern
    $y(x(y\cdots(yy)))$.} Since $n \ge 3$, we have $Z = y = W$,
    so $|W\cdots(WW)| = n|W| = n|Z|$,
    contradicting $|x(y\cdots(yy))| > n|y|$.
\end{proof}

n43383.content:
\begin{lemma}[1485 equivalent to 2162]\label{1485-dual}\uses{eq1485}\leanok\lean{WeakCentralGroupoid.dual_eqn}
  \href{https://teorth.github.io/equational_theories/implications/?1485}{E1485} is equivalent to the dual law
  \begin{equation}\label{2162}
   x = ((y \diamond z) \diamond x) \diamond(x \diamond y)
  \end{equation}
  (equation 2162).
\end{lemma}

n43384.content:
\begin{proof}
  It suffices to prove that \Cref{1485} implies \Cref{2162}. Write $w = y \diamond z$, then from \Cref{1485} we can write $z = z_1 \diamond z_2$ with $z_1 = z \diamond z$ and $z_2 = z \diamond(z \diamond z)$, and then by \Cref{1485}
  $$ y = (z_2 \diamond y) \diamond(y \diamond(z_1 \diamond z_2)) = (z_2 \diamond y) \diamond w.$$
  From another application of \Cref{1485} we have
  $$ x = (w \diamond x) \diamond(x \diamond((z_2 \diamond y) \diamond w)) = ((y \diamond z) \diamond x) \diamond(x \diamond y)$$
  as required.
\end{proof}

n43385.content:
\begin{lemma}[Equivalent characterization of graph]\label{graph-dual}\uses{eq1485}\leanok\lean{WeakCentralGroupoid.Path.def'}
  One has $x \to y$ if and only if $x = w \diamond y$ for some $w$.
\end{lemma}

n43386.content:
\begin{proof}\uses{1485-dual}
  If $x \to y$ then $y = x \diamond z$, then writing $z = z_1 \diamond z_2$ as before we obtain
  $$ x = (z_2 \diamond x) \diamond(x \diamond(z_1 \diamond z_2)) = (z_2 \diamond x) \diamond y$$
  giving the forward implication. The backwards implication follows by duality.
\end{proof}

n43387.content:
\begin{lemma}[Claim 4]\label{claim-4}\uses{eq1485}\leanok\lean{WeakCentralGroupoid.isGood_five}
  If $a \to b \to c \to d \to e \to a$ is a 5-cycle in the directed graph, and $a \to b \to c$ and $c \to d \to e$ are good paths, then $b \to c \to d$ is also good.
\end{lemma}

n43388.content:
\begin{proof}\uses{graph-dual}
  If $a \to b \to c$ is good then $b = a \diamond c$; if $c \to d \to e$ is good then $d = c \diamond e$; and if $e \to a$ then $a = e \diamond z$ for some $z$ by definition. By \Cref{2162} we then have
  $$ c = ((e \diamond z) \diamond c) \diamond(c \diamond e) = b \diamond d$$
  so $b \to c \to d$ is good.
\end{proof}

n43389.content:
\begin{lemma}[Reversing the claims]\label{rev-claim}\uses{claim-4}\leanok\lean{RelaxedWeakCentralGroupoid.strictify}
  Let $G$ be a directed graph, with some paths of length two in the graph designated as ``good'', in such a way that Claims 1-4 hold. Then there is a weak central groupoid structure on the vertices of $G$ such that the good paths are precisely the paths of the form $x \to x \diamond y \to y$.
\end{lemma}

n43390.content:
\begin{proof}
  Define an operation $\diamond: G \times G \to G$ by defining $x \diamond y$ to be the unique vertex $z$ for which one has a good path $x \to z \to y$; this is well-defined by Claim 1, and by Claims 2-3, the property $x \to y$ holds if and only if $y = x \diamond z$ for some $z$, and also if and only if $x = w \diamond y$ for some $w$. In particular, for all $x,y,z$, we have a $5$-cycle
  $$ y \to y \diamond x \to x \to x \diamond(z \diamond y) \to (z \diamond y) \to y$$
  with $y \to y \diamond x \to x$ and $x \to x \diamond(z \diamond y) \to (z \diamond y)$ good, hence by Claim 4 we have \Cref{1485} as required.
\end{proof}

n43391.content:
\begin{proposition}[Completion property]\label{greedy-prop}\uses{eq1485}\leanok\lean{RelaxedVeryWeakCentralGroupoid.Greedy.exists_extension}
  Let $G_0$ be a directed graph satisfying claims 1', 2, 3, 4. Then any finite partial extension of $G_0$ with carrier $G_0 \times \mathbb{N}$ (and projection map $\pi(a,n) = a$) can be completed to a complete extension.
\end{proposition}

n43393.content:
\begin{theorem}[1485 does not imply 1483]\label{1485-refutes}\uses{eq1485}\leanok\lean{Refutation_1485.not_3457,Refutation_1485.not_3511,Refutation_1485.not_2087_2124}
  \href{https://teorth.github.io/equational_theories/implications/?1485}{E1485} does not imply any of the following laws:
  \begin{itemize}
   \item Equation 3457: $x \diamond x = x \diamond((x \diamond x) \diamond y)$.
   \item Equation 2087: $x = ((y \diamond x) \diamond x) \diamond(x \diamond x)$.
   \item Equation 2124: $x = ((y \diamond y) \diamond x) \diamond(x \diamond x)$.
   \item Equation 3511: $x \diamond y = x \diamond((x \diamond y) \diamond x)$.
  \end{itemize}
\end{theorem}

n43394.content:
\begin{proof}\uses{greedy-prop, rev-claim}
  Computer check reveals that the carrier $G_0=\{0,1,2,3 ,4\}$ with incidence matrix
  $$
  \begin{pmatrix}
   1 & 1 & 0 & 0 & 1 \\
   1 & 1 & 0 & 1 & 0 \\
   0 & 0 & 1 & 1 & 1 \\
   1 & 0 & 1 & 0 & 0 \\
   0 & 1 & 1 & 0 & 0 \\
  \end{pmatrix}
  $$
  is a relaxed weak central groupoid if we declare the paths $0 \to 0 \to 0$, $0 \to 0 \to 1$, $0 \to 1 \to 1$, $1 \to 0 \to 0$, $1 \to 1 \to 0$, $1 \to 1 \to 1$ to be bad, and all other paths in the directed graph to be good. We can also check the following axioms:
  \begin{itemize}
   \item Anti-3457: There exist $x,y,z,w$ with $x \to z \to x$,  $z \to w \to y$ both good, and $x \to z \to w$ bad. (One can take $x=1$, $y=4$, $z = 0$, $w = 0$.)
   \item Anti-2087: There exist $x,y,z,w,u$ with $y \to z \to x$, $z \to w \to x$, and $x \to u \to x$ good, and $w \to x \to u$ is bad. (One can take $x=1, y=2$, $z=4$, $w=1$, $u=0$.)
   \item Anti-2124: There exists $x,y,z,w,u$ with $y \to z \to y$, $z \to w \to x$ and $x \to u \to x$ good, and $w \to x \to u$  bad. (One can take $x=1$, $y=2$, $z=4$, $w = 1$, $u=0$.)
   \item Anti-3511: There exists $x,y,z,w$ with $x \to z \to y$ and $z \to w \to x$ good, and $x \to z \to w$ bad. (One can take $x=1$, $y=3$, $z = 1$, $w=0$.)
  \end{itemize}

  Let $G_*$ be a finite partial extension of $G_0$ to be chosen later. By \Cref{greedy-prop}, we can complete this to a complete weak central groupoid $G$ with carrier $G_0 \times \mathbb{N}$. Depending on how we choose $G_*$, we can ensure that this $G$ refutes one of the four laws 3457, 2087, 2124, 3511:
  \begin{itemize}
   \item Refuting 3457: Let $x,y,z,w$ be as in the claim Anti-3457, then select $G_*$ to be the directed graph with edges $(x,0) \to (z,2) \to (x,0) \to (z,2) \to (w,3) \to (y,1)$. One can check that this is a partial extension, and that $G$ will refute 3457 with $x,y$ replaced by $(x,0),(y,1)$.
   \item Refuting 2087: Let $x,y,z,w,u$ be as in the claim Anti-2087, then select $G_*$ to be the directed graph with edges $(y,1) \to (z,2) \to (x,0)$ and $(z,2) \to (w,3) \to (x,0) \to (u,4) \to (x,0)$. One can check that this is a partial extension, and that $G$ will refute 2087 with $x,y$ replaced by $(x,0),(y,1)$.
   \item Refuting 2124: Let $x,y,z,w,u$ be as in the claim Anti-2124, then select $G_*$ to be the directed graph with edges $(y,1) \to (z,2) \to (y,1)$ and $(z,2) \to (w,3) \to (x,0) \to (u,4) \to (x,0)$. One can check that this is a partial extension, and that $G$ will refute 2124 with $x,y$ replaced by $(x,0),(y,1)$.
   \item Refuting 3511: Let $x,y,z,w$ be as in the claim Anti-3511, then select $G_*$ to be the directed graph with edges $(x,0) \to (z,2) \to (y,1)$ and $(z,2) \to (w,3) \to (x,0)$. One can check that this is a partial extension, and that $G$ will refute 3511 with $x,y$ replaced by $(x,0),(y,1)$.
  \end{itemize}
\end{proof}

n43395.content:
\begin{lemma}[Basic properties of 677 magma]\label{677-basic} Let $M$ be a finite magma satisfying \eqref{677}.
  \begin{itemize}
  \item (i)  The left multiplication operators $L_y: M \to M$ are all invertible, with $L_y^{-1} x = x \diamond R_y L_y x$.
  \item (ii) If $x,y \in M$ and $y \diamond x = x$, then $y = Sx \diamond x$.  In particular, 255 holds if and only if the equation $y \diamond x = x$ is solvable for every $x$.
  \item (iii)  For all $x,y \in M$, we have $x = L_y x \diamond R_y L_y^2 x$.
\end{itemize}
\end{lemma}

n43404.content:
\begin{lemma}[Additional property]\label{op-2-677}  If $x,y \in M_X$, then
  $$ x \diamond((y \diamond x) \diamond y) = (x, (y \diamond x) \diamond y).$$
\end{lemma}

n43405.content:
\begin{proof} Write $z := y \diamond x$, $u = z \diamond y$, $v = x \diamond u$.  Our task is to show that $v = (x,u)$.

From \Cref{op-prop} we know that $y$ is upper bounded by one of $z,x$, $z$ is upper bounded by one of $u,y$, and $x$ is upper bounded by one of $u,v$.  So out of $x,y,z,u,v$, the only elements that can be maximal in this set are $u$ and $v$.  If $v$ is maximal, then by \Cref{op-prop} we have $v = (x,u)$ as required, hence we may assume for contradiction that $u$ is maximal.  From \Cref{op-prop}, this implies that $u = (z,y)$ and $u = (u_L, (x \diamond u_L) \diamond x)$, hence $u_L = z$ and $y = (x \diamond z) \diamond x$.

