n43416.content:
\begin{theorem}[854 does not imply 3316, 3925]\label{854-anti}\leanok\lean{Refutation_854.not_3316_3925}  The laws
\begin{equation}\label{3316}
  x \diamond y = x \diamond(y \diamond(x \diamond y))
\end{equation}
and
\begin{equation}\label{3925}
  x \diamond y = (x \diamond(y \diamond x)) \diamond y
\end{equation}
are not implied by \href{https://teorth.github.io/equational_theories/implications/?854}{E854}.
\end{theorem}

n43420.content:
\begin{lemma}[854 equivalences, II]\label{854-equiv-2}  For $x,y$ in a 854 magma, the following are equivalent.
  \begin{itemize}
  \item (i) $y \leq x$.
  \item (ii) $x \diamond y \to x$.
  \item (iii)  For all $z$, $y \to z$ implies $x \to z$.
  \item (iv) $x \to x \diamond y$.
  \end{itemize}
\end{lemma}

n43421.content:
\begin{proof}  The equivalence of (i) and (ii) is by definition.  If (ii) holds and $y \to z$, then by \Cref{854-equiv} we have $x = u \diamond(x \diamond y)$ and $z = v \diamond y$ for some $u,v$, hence
  $$ z \diamond x = z \diamond(x \diamond((v \diamond y) \diamond(x \diamond y))) = z \diamond((u \diamond(x \diamond y)) \diamond(z \diamond(x \diamond y))) = z,$$
giving the desired claim $x \to z$.  Now if (iii) holds, note from \Cref{854-equiv} that $y \to x \diamond y$, hence $x \to x \diamond y$ by (iii), so that $(x \diamond y) \diamond x = x \diamond y$, giving (iv).  Finally, if (iv) holds, note that
\begin{align*}
  x \diamond((x \diamond y) \diamond x) &= x \diamond( ((x \diamond y) \diamond((y \diamond y) \diamond((x \diamond y) \diamond y))) \diamond x) \\
  &= x \diamond(((x \diamond y) \diamond((y \diamond y) \diamond(x \diamond y))) \diamond(x \diamond((y \diamond y) \diamond(x \diamond y)))) \\
  &= x
\end{align*}
and hence by (iv) $x \diamond(x \diamond y) = x$, giving (ii).
\end{proof}

n43425.content:
\begin{corollary}[854 extension]\label{extend-854}\leanok\lean{Refutation_854.Greedy.exists_extension}
Suppose one has a partial 854 magma on $\mathbb{N}$ that is only finitely defined.  Then it can be extended to a complete 854 magma that additionally satisfies the no idempotence law, the monotonicity law, the auxiliary law, and the unique factorization law.
\end{corollary}

n43431.content:
\begin{lemma}[The 854 relation]\label{854-relation}  Let $M$ be an $854$ magma, and let $\to$ be the associated operation, thus $x \to y$ if $y \diamond x = y$.  Then $x \to y$ holds under any of the following assumptions:
  \begin{itemize}
  \item (i) $y = a \diamond x$ for some $a$.
  \item (ii) $x = a \diamond(y \diamond b)$ for some $a,b$ with $b \to a$.
  \item (iii) $y = a \diamond(x \diamond b)$ for some $a,b$ with $b \to a$ and $x \diamond b \to x$.
  \item (iv) $x = a \diamond y$ for some $a,z$ with $z \to a, y$.
  \item (v) $x = a \diamond y$ for some $a$, with either $a=y$, $a = y \diamond z$, or $y = a \diamond z$ for some $z$.
  \end{itemize}
\end{lemma}

n43433.content:
\begin{definition}[Relation on the free group]\label{free-relate} For $x,y \in M_X$, we have $x \to y$ if and only if one of the following holds:
\begin{itemize}
\item (i) $x = y_R$.
\item (ii) $y = x_{RL}$ and $x_{RR} \to x_L$.
\item (iii) $x = y_{RL}$, $y_{RR} \to y_L$, and $y_R \to y_{RL}$.
\item (iv) $y = x_R$, and there exists $z \in \{ x_{LR}, x_{LRL}, x_{RR}, x_{RRL} \}$ such that $z \to x_L$ and $z \to x_R$.
\item (v)  $y = x_R$, and one of the claims $x_L = x_R$, $x_L = x_{RL}$, or $x_R = x_{LL}$ holds.
\end{itemize}
Here we adopt the convention that a claim can only hold if all terms in it are well-defined, for instance claim (ii) can only hold if $x_{RL}$ is well-defined.
\end{definition}

n43435.content:
\begin{proof}  Let  $f: X \to M$ be a function from $X$ to an $854$ magma $M$, then $\varphi_f$ is a homomorphism from $M_X$ (with the operation $*$) to $M$.  We claim that the restriction of $\varphi_f$ to $M_{X,854}$ is a homomorphism from $M_{X,854}$ (with operation $\diamond$) to $M$.  Since $\varphi_f$ was already a homomorphism for $*$, it suffices to show that $\varphi_f$ preserves $\to$: that is to say, for any $x,y \in M_{X,854}$, that $x \to y$ implies $\varphi_f(x) \to \varphi_f(y)$.  By definition, one of the five scenarios (i)-(v) in \Cref{free-relate} holds, and in each case one can establish the claim from the corresponding claim of \Cref{854-relation} and an induction on the max-length of the claim $x \to y$.

It remains to show that $M_{854}$ actually satisfies 854, that is to say that
$$ (y \diamond z) \diamond(x \diamond z) \to x$$
for all $x,y,z \in M_{854}$.  Writing $w = y \diamond z$, we have $z \to w$ by \Cref{free-relate}(i), and we need to show that $w \diamond(x \diamond z) \to x$.  We divide into four cases.

Case 1: $x \diamond z \to w$, $z \to x$.  Here we have $x \diamond z = x$ and $w \diamond(x \diamond z) = w$.  We now have $z \to x,w$ and $x \to w$, and we need to show that $w \to x$.

From \Cref{one} we know that one of
\begin{equation}\label{one-1}
  z = x_R, z = x_{RL}, x = z_R, x = z_{RL}
\end{equation}
holds, one of
\begin{equation}\label{one-2}
  z = w_R, z = w_{RL}, w = z_R, w = z_{RL}
\end{equation}
holds, and one of
\begin{equation}\label{one-3}
  x = w_R, x = w_{RL}, w = x_R, w = x_{RL}
\end{equation}
holds.

We split into subcases using \Cref{one-3}.
\begin{itemize}
  \item If $x = w_R$ then the claim follows from \Cref{free-relate}(i).
  \item If $w = x_{RL}$ then from \Cref{free-relate}(iii) we have $x_{RR} \to x_L$, and then the claim follows from \Cref{free-relate}(ii).
  \item If $x = w_{RL}$, then $w_{RR} \to w_L$ by \Cref{free-relate}(ii) and from \Cref{free-relate}(iii) we will be done if we can show that $w_R \to w_{RL}$.  If $z = w_R$ then this follows from $z \to x$.  The claim $z = w_{RL}$ is not compatible with \Cref{one-1}, since $z=x$ in that case. If $w = z_R$ then $x = z_{RRL}$, and this is only compatible with \Cref{one-1} if $x = z_{RL}$, thus $z = a * (x * (x * b))$ and $w = x  * (x * b)$ for some $a,b$.  In order to have $x = w_{RL}$ in \Cref{one-3}, we must have $b \to x$ by \Cref{free-relate}(iii), but then $x*b$ would not lie in $M_{854}$, a contradiction.
