n43440.content:
\begin{lemma}[Construction of 1323 magmas]\label{1323-construct}\leanok\lean{Eq1323.eq1323_if_conditions}  Suppose that $M$ is a magma such that
  \begin{equation}\label{lr}
    R_{Sy} L_{Sy} = 1
   \end{equation}
and
\begin{equation}\label{lr-simp}
  L_{y} R_{y} = R_{Sy}
\end{equation}
hold.  Then the magma satisfies 1323.
\end{lemma}

n43442.content:
\begin{lemma}[Bijections]\label{bij}\leanok\lean{Eq1323.ϕ}
  Let $G$ be a countably infinite abelian torsion group of exponent $2$.  Then there exists a bijection $\phi_a: G \to \mathbb{Q}^\times$ for each $a \in G \backslash \{0\}$ such that
 $\phi_a(0) = 1$ and $\phi_a(a+b) = -\phi_a(b)$ for all $b \in G$, so in particular $\phi_a(a)=-1$.
 \end{lemma}

n43443.content:
\begin{proof}
  Such a bijection can be easily constructed from the axiom of choice and a greedy algorithm, defining $\phi_a$ one pair $\{b,a+b\}$ at a time.
 \end{proof}

n43444.content:
\begin{lemma}[Building a magma]\label{build-magma}\leanok\lean{Eq1323.op}\lean{Eq1323.op_RSy_LSy_eq_Id}\lean{Eq1323.op_Ly_Ry_eq_LSy}  Let $G$ be a countably infinite abelian torsion group of exponent $2$, and let $\phi_a$ be as in the previous lemma.  Let $N$ be the set of pairs $(x,a)$ with $x \in \mathbb{Q}^\times$ and $a \in G \backslash \{0\}$, and let $M = G \uplus N$ be the disjoint union of $G$ and $N$.  Suppose that we have an operation $\diamond: M \times M \to M$ satisfying the following axioms:
\begin{itemize}
\item (i) We have
\begin{equation}\label{op-0}
  a \diamond b = a+b
\end{equation}
for $a,b \in G$.
\item (ii) We have
 \begin{equation}\label{op-1}
  (x,a) \diamond b = (\phi_a(b) x, a)
 \end{equation}
 \begin{equation}\label{op-2}
   b \diamond(x,a) = (x / \phi_a(b), a)
 \end{equation}
 and
 \begin{equation}\label{op-3}
   (\phi_a(b) x,a) \diamond(x,a) = a+b
 \end{equation}
 for $x \in \mathbb{Q}^\times$, $b \in G$, and $a \in G \backslash \{0\}$.
\item (iii) If $a,b,0 \in G$ are distinct and
$(x,a) \diamond(y,b) = (z,c)$ for some $x,y,z \in \mathbb{Q}^\times$ and $c \in G$, then $(y,b) \diamond(z,c) = (\phi_a(b) x,a)$.
\end{itemize}
Then \Cref{lr}, \Cref{lr-simp} and hence \Cref{1323} holds.
\end{lemma}

n43446.content:
\begin{definition}[Partial solution]\label{partial-1323} A \emph{partial solution} is a finite family ${\mathcal F}$ of tuples $(x,y,z,a,b,c) \in (\mathbb{Q}^\times)^3 \times G^6$ with $a,b,c,0$ distinct, such that the tuples
$(\phi_a(b)^n x,a, \phi_b(c)^n y,b)$, $(\phi_b(c)^n y,b,\phi_c(a)^n z,c)$, $(\phi_c(a)^n z,c,\phi_a(b)^{n+1} x, a)$ for $(x,y,z,a,b,c) \in {\mathcal F}$ and $n \geq 0$ are all distinct.
\end{definition}

n43455.content:
\begin{definition}[1516 seed]\label{1516-seed}  A \emph{1516 seed} is a finite collection $E$ of pairs $(a,b)$ with $a,b \in \mathbb{Z}$ satisfying the following axioms:
  \begin{itemize}
  \item Axiom 1: $(0,0) \in E$.
  \item Axiom 2: If $(a,b) \in E$ and $a \neq 0$, then $b \neq 0, -a$.
  \item Axiom 3: If $(a,b), (a,b') \in E$, then $b=b'$.
  \item Axiom 4: If $(a,b), (b,c) \in E$, then $(c-a,-a) \in E$.
  \item Axiom 5: If $(b,a), (b',a), (-b, d), (-b',d') \in E$ with $b \neq b'$, then $b+d \neq d', b'+d'$.
  \end{itemize}
An \emph{extension} of a 1516 seed $E$ is a 1516 seed $E'$ that contains $E$.
\end{definition}

n43460.content:
\begin{corollary}[Base magma]\label{1516-base} There exists a 1516 magma with carrier $\mathbb{Z}$ with the properties that
  \begin{itemize}
    \item (i) $Sa=a$ for all $a$.
    \item (ii) For any distinct $a,b \in \mathbb{Z}$, the equation $R_a c = b$ has at least four solutions $c$.
    \item (iii) For each $a \in \mathbb{Z}$, there exist at least two $b \neq a$ such that $L_a R_a b = b$.
  \end{itemize}
\end{corollary}

n43462.content:
\begin{lemma}[Useful elements]\label{aux}  One can assign $c_{y,b} \in \mathbb{Z}$ for each $y = (a,c,n) \in G'$ and $b \in \mathbb{Z}$ with the following properties:
\begin{itemize}
\item (i)  For all $y = (a,c,n) \in G'$ and $b \in \mathbb{Z}$, $c_{y,b} \neq a,b,c$ and $L_a L_{c_{y,b}} b = c_{y,b}$.
\item (ii) For all $y \in G'$, the map $b \mapsto c_{y,b}$ is injective.
\end{itemize}

\end{lemma}

n43465.content:
\begin{proof}  We define $L_{c'} y$ for $y = (a,c,n) \in G'$ as follows:
\begin{itemize}
  \item (i) If $c' = a$ and $n=0$, then $L_{c'} y := a$.
  \item (ii) If $c' = a$ and $n \neq 0$, then $L_{c'} y := (a,c,0)$.
  \item (iii) If $c' = c_{y,b}$ for some $b$, then $L_{c'} y := b$.
  \item (iv) In all other cases, $L_{c'} y$ is undefined.
\end{itemize}
We of course also define $L_{c'} y$ for $y \in \mathbb{Z}$ using \Cref{1516-base}.

From Lemma \ref{aux} we see that this is a well-defined operation, with $L_c y$ undefined for any $y = (a,c,n) \in G'$.  So properties (a)-(e) and (g) are clear from construction.  Property (e) is also clear from construction in each of the three cases (i), (ii), (iii) (for (i), (ii) we also use the fact that $L_a a = a$).
\end{proof}

n43467.content:
\begin{proof} Write $y = (a,c,n)$. Because $L_a: \mathbb{Z}\to \mathbb{Z}$ and $L_{c'}: \mathbb{Z}\to \mathbb{Z}$ are surjective, we can find $b \in \mathbb{Z}$ such that $L_a L_{c'} b = c'$.  If we had $b=c'$, then $L_a c' = c'$, which from \eqref{1516} (and $Sc' = c'$) implies that $a = c'$, which contradicts the undefined nature of $L_{c'} y$ thanks to properties (b), (c) of a partial solution.  Hence, $b \neq c'$.
  We then set $L_{c'} y := b$.  It is then clear that all the properties (a)-(g) of a partial solution are maintained.
\end{proof}

n43469.content:
\begin{proof} Write $y = (a,c,n)$. There are several cases.
  \begin{itemize}
    \item Case 1: $L_{c'} y = w$ for some $w \in G'$.  By Lemma \ref{aux}, $c_{w,c'}$ is distinct from $c'$, and from property (d) of a partial solution, $L_{c_{w,c'}} w = c'$.  By property (e) of a partial solution, we can find $z = (c_{w,c'}, c', n')$ such that $L_{c'} z$ is currently undefined.  Then set $L_{c'} z := y$, so that we have $L_{c_{w,c'}} L_{c'} L_{c'} z = c'$.  One then verifies that all the axioms (a)-(g) of a partial solution are valid in this case.
    \item Case 2: $c' \neq a$ and $L_{c'} y = b$ for some $b \in \mathbb{Z}$. By property (g) of a partial solution, $c' \neq b$.  By \Cref{1516-base}, we can find $a'$ such that $L_{a'} b = R_b a' = c'$ and $a' \neq c'$.  By property (e) of a partial solution, we can find $z = (a', c', n')$ such that $L_{c'} z$ is currently undefined.  Then set $L_{c'} z = y$, so that we have $L_{a'} L_{c'} L_{c'} z = c'$. One then verifies that all the axioms (a)-(g) of a partial solution are valid in this case.
    \item Case 3: $c' \neq a$ and $L_{c'} y$ is currently undefined.  Use Lemma \ref{first-ext} set $L_{c'} y$ equal to some $b \in \mathbb{Z}$, then apply the Case 2 analysis.
    \item Case 4: $c' = a$.  Because we are excluding the case $n=0$, we are now in Case 1 thanks to property (c) of a partial solution.
  \end{itemize}
\end{proof}

n43471.content:
\begin{proof}
By iterating \Cref{first-ext} and \Cref{second-ext} in alternation, we can find an increasing chain of partial solutions with the property that for any $y = (a,c,n) \in G'$ and $c' \in \mathbb{Z}$ and any natural number $k$, excluding the case where $c'=a$ and $n=0$, that one can find a partial solution on this chain for which $L_{c'} y$ is defined, and such that $L_{c'} z = y$ for at least $k$ distinct choices of $z \in G'$.  Taking the limit of this chain, we can then find a fully defined operation $L_{c'} y$ for $c' \in \mathbb{Z}$ and $y \in G$ satisfying the properties (a)-(d), (f), (g) (but not (e)) of a partial solution, with the property that
$y = (a,c,n) \in G'$ and $c' \in \mathbb{Z}$, excluding the case $c'=a$ and $n=0$, that there are infinitely many $z \in G'$ such that $L_{c'} z = y$.  The excluded case $c'=a, n=0$ is also covered by property (b) of a partial solution.  The claim follows.
\end{proof}

n43473.content:
\begin{proof}  We can work with a single $x \in G'$.  Our task is to find a function $L_x$ for which
\begin{equation}\label{axioma-again}
   L_x x = Sx
\end{equation}
and
\begin{equation}\label{axiomb-again}
  L_{Sy} L_x L_x y = x
\end{equation}
for all $y \in G$ (note that $L_{Sy}$ is already fully constructed).

Define a \emph{seed} to be an injective partial function $L_x$ defined on finitely many values and satisfying \Cref{axioma-again}, as well as \Cref{axiomb-again} whenever $L_x L_x y$ is defined.
If there is a $y \in G$ for which $L_x y$ is currently undefined, then by hypothesis $y$ is equal to $L_x z$ for at most one $z$.
If such a $z$ exists, we set $L_x y$ to be an element of $\{ w: L_{Sz} w = x \}$ different from $y$ that is not already in the domain or range of $L_x$; we are able to do so thanks to the infinite surjectivity (\Cref{1516-base} (ii)) and the fact that the domain and the range of $L_x$ are finite.
If no such $z$ exists, we set $L_x y$ to be arbitrary element of $G$ not already in the domain or range.  In either case, we see that the seed property is preserved.  Starting from the seed in which $L_x$ is only defined on $x$ and maps it to $Sx$, we obtain the claim.
\end{proof}

n43475.content:
\begin{proof}
  Let us define the element $x_0 := (0, 1, 0) \in G'$.
  Since $S x_0 = 0$, we know that $0 \diamond x_0 = 0$ (see the first part of the proof of \Cref{axiom-b}).
  Therefore, $x_0$ does not satisfy the 255 equation, as we have
  $$((x_0 \diamond x_0) \diamond x_0) \diamond x_0 = (0 \diamond x_0) \diamond x_0 = 0 \diamond x_0 = 0 \neq x_0.$$
\end{proof}

n43476.content:
\begin{theorem}[Extending a 1729 magma]\label{mag}  Let $SM$ be a magma satisfying 1729, and let $N$ be another set disjoint from $SM$, and set $M := SM \uplus N$.  Suppose that we have a squaring map $S': N \to SM$ (which will complement the existing squaring map $S: SM \to SM$), and bijections $L'_a, R'_a: N \to N$ for all $a \in SM$ (which will complement the existing bijections $L_a, R_a: SM \to SM$ coming from $SM$), satisfying the following axioms:
  \begin{itemize}
  \item (i) For all $a \in SM$, we have $L'_a = (R'_a)^{-1} (L'_{Sa})^{-1}$.
  \item (ii) For all $y \in N$, the elements $R'_a y \in N$ are distinct from each other and from $y$ as $a \in SM$ varies.
  \item (iii)  If $R'_a x = y$ for some $a \in SM$ and some $x,y \in N$, then $L'_{S'y} L_{L_{S'x}^{-1} a} y = x$.
  \item (iv)  For all $x \in N$, we have $(L'_{S'x})^2 x = x$.
  \end{itemize}
Suppose also that we have an operation $\diamond': N \times N \to M$ satisfying the following axioms:
\begin{itemize}
  \item (v)  For all $x \in N$, we have $x \diamond' x = S'x$.
  \item (vi)  For all $y \in N$ and $a \in SM$, we have $R'_a y \diamond' y = L_{S'y}^{-1} a$.
  \item (vii)  For all $x,y \in N$ with $x \diamond' y$ not already covered by rules (v) or (vi), we have $x \diamond' y = z$ for some $z \in N$.  Furthermore, $z \diamond' x = (L'_{S'x})^{-1} y$.
\end{itemize}
Then one can endow $M$ with an operation $\diamond'': M \times M \to M$ satisfying 1729 defined as follows:
\begin{itemize}
\item  If $a,b \in SM$, then $a \diamond'' b = a \diamond b$.
\item  If $a \in SM$ and $x \in N$, then $a \diamond'' b := L'_a b$.
\item  If $x \in N$ and $a \in SM$, then $b \diamond'' a := R'_a b$.
\item  If $x,y \in N$, then $x \diamond'' y := x \diamond' y$.
\end{itemize}
Furthermore, the 817 law $x \diamond'' SS' x = x$ fails for any $x \in N$.
\end{theorem}

n43484.content:
\begin{definition}[Definition of $R'_a$]\label{ra-defn}\uses{sm-def, n-def}\lean{Eq1729.R'}\leanok We set
  \begin{equation}\label{ra-def}
    R'_a x := e_a x
  \end{equation}
  for all $a \in SM$ and $x \in N$.
\end{definition}

n43487.content:
\begin{lemma}[Using $L'_0$ to construct $L'_a$]\label{l0-la}\lean{Eq1729.L',Eq1729.L'_0_eq_L₀'}\leanok  Suppose we have a bijection $L'_0: N \to N$ that satisfies axiom (i'), and then define $L'_a$ for all $a \in SM$ by the formula \eqref{la0}.  Then this recovers $L'_0$ when $a=0$ (to formalize this it may be convenient to give $L'_0$ and $L'_a$ distinct names), and the $L'_a$ are all bijections and satisfy axiom (i).  Furthermore, we have
\begin{equation}\label{la1}
  (L'_a)^{-1} := (R'_{2a})^{-1} L'_0 R'_0 R'_{a}
\end{equation}
for all $a \in SM$.
\end{lemma}

n43491.content:
\begin{definition}[Partial solution]\label{part-sol}\uses{sm-def, n-def}\lean{Eq1729.PartialSolution}\leanok  A \emph{partial solution} $(L'_0, \diamond', S', {\mathcal I})$ is a collection of the following data:
\begin{itemize}
  \item A partially defined function $L'_0: N \to N$, defined on a finite union of right cosets of $\langle e_0\rangle$;
  \item A partially defined operation $\diamond': N \times N \to M$, defined on a finite set;
  \item A partially defined function $S': N \to SM$, defined on a finite set; and
  \item A finite collection ${\mathcal  I}$ of ``pending identities'' $I[x,y,z]$, which one can think of either as ordered triples of elements $x,y,z \in N$, or as formal strings of the form ``$z \diamond' x = (R'_{2S'x})^{-1} L'_0 R'_0 R'_{S'x} y$'' for some $x,y,z \in N$.
\end{itemize}

Furthermore, the following axioms are satisfied:
\begin{itemize}
  \item (i'')  $L'_0 x$ is defined and equal to $y$, then we have the identities \Cref{itero}, \Cref{itero-2} for all $n\in \mathbb{Z}$.
  \item (S) If $S'x$ is defined for some $x \in N$, then $S'y$ is defined for all $y \leq x$.
  \item (iii'') If $R'_a x = y$ for some $a \in SM$ and some $x,y \in N$, and $S'x, S'y$ are defined, then $(R'_{S'y})^{-1} L'_0 R'_{2S'y} (R'_{a-S'x})^{-1} L'_0 R'_{2(a-S'x)} y$ is defined and equal to $x$.
  \item (iv'') If $x \in N$ is such that $S'x$ is defined, then $(R'_{S'x})^{-1} L'_0 R'_{2S'x} (R'_{S'x})^{-1} L'_0 R'_{2S'x} x$ is defined and equal to $x$.
  \item (v'')  If $x \in N$ and $x \diamond' x$ is defined, then $S'x$ is defined and equal to $x \diamond' x$.
  \item (vi'')  For all $y \in N$ and $a \in SM$, if $R'_a y \diamond' y$ is defined, then $a - S'y$ is defined and equal to $R'_a y \diamond' y$.
  \item (vii'')  For all $x,y \in N$ and $x$ is not equal to $y$ or $R'_a y$ for any $a \in SM$, and $x \diamond' y$ is defined, then it is equal to some $z \in N$.  Furthermore, either $I[x,y,z]$ is a pending identity, or else $z \diamond' x$ and $(R'_{2S'x})^{-1} L'_0 R'_0 R'_{S'x} y$ are defined and equal to each other.
  \item (P) If $I[x,y,z]$ is a pending identity, then $x,y,z \in N$, and $Sx$ and $z \diamond' x$ are undefined.  Furthermore, $z$ is not equal to $x$ or $R'_a x$ for any $a \in SM$, and $y$ is not of the form $(R'_0)^n x$ or $(R'_0)^n y_0$ for any $n$, where $y_0$ is the parent of $x$.
  \item (P') If $I[x,y,z]$ and $I[x,y',z]$ are pending identities, then $y=y'$.
  \item (P'') If $I[x,y,z]$ is a pending identity, then $x \diamond' y = z$.
  \item (L) If $y$ is the parent of $x$ with $x = R'_a y$, and $(R'_{a-S'y})^{-1} L'_0 R'_{2(a-S'y)} x$ is defined, then it is not equal to $x$.
\end{itemize}

We say that one partial solution $(\tilde L'_0, \tilde \op', \tilde S', \tilde {\mathcal I})$ \emph{extends} another if $(L'_0, \diamond', S',  {\mathcal I})$ if $\tilde L'$ is an extension of $L'_0$, $\tilde \op'$ is an extension of $\diamond'$, and $\tilde S'$ is an extension of $S'$.  (No constraint is imposed on the final components $\tilde {\mathcal I}, {\mathcal I}$.)  This is a preordering.
\end{definition}

n43494.content:
\begin{lemma}[Chain of partial solutions]\label{chain}\uses{part-sol}\lean{Eq1729.use_chain}\leanok  Suppose that one has a sequence
$(L'_{0,n}, \diamond'_{n}, S'_{n}, {\mathcal I}_n)$ of partial solutions, each one an extension of the previous, such that for any $x, y \in N$, $L'_{0,n} x$, $x \diamond'_{n} y$, and $S'_n x$ are defined for some $n$.  Then there exists a 1729 magma that does not satisfy 817.
\end{lemma}

n43500.content:
\begin{proposition}[Enlarging $S'$ with induction hypothesis and axioms]\label{enlarge-S-induct-axioms}\lean{Eq1729.enlarge_S'_induction_with_axioms}\leanok  Suppose one has a partial solution in which $S'x$ is undefined for some $x \in N$, but $S'y$ is defined for all $y < x$.  (This hypothesis is vacuous for $x=1$.) Let $y_0$ be the parent of $x$ (if $x \neq 1$), and assume the following additional axioms:
  \begin{itemize}
    \item (A) If $R'_a x = y_0$ for some $a \in SM$, then $L'_0 R'_{S' y_0} x$ is defined.
    \item (B) If $x = R'_a y_0$ for some $a \in SM$, then $L'_0 R'_{2(a-S'y_0)} x$ is defined.
    \item (C)  If $I[x,y,z]$ for some $y,z \in N$, and $S'z$ is defined, then $L'_0 R'_0 R'_{S'z} x$ is defined.
    \end{itemize}
  Then one can extend the partial solution so that $S'x$ is now defined.
\end{proposition}

n43503.content:
\begin{proof}
  \uses{enlarge-l0-many,enlarge-S-induct-axioms}\leanok  Let $y_0$ be the parent of $x$, that is to say the unique neighbor of $x$ in the path to $1$ (this is only defined for $x \neq 1$), then by axiom (i'') $y_0$ is the unique neighbor for which $S'y_0$ is defined, and we either have $x = R'_a y_0$ or $R'_a x = y_0$ for some unique $a \in SM$.

  By using \Cref{enlarge-l0-many}, we may impose axioms (A), (B), (C) without loss of generality, as this only imposes a finite set of conditions.  The claim now follows from \Cref{enlarge-S-induct-axioms}.
\end{proof}

n43509.content:
\begin{proof}\uses{partial-exist, enlarge-l0, enlarge-S, enlarge-op,chain}\leanok
  Starting from \Cref{partial-exist} and applying \Cref{enlarge-l0}, \Cref{enlarge-S}, \Cref{enlarge-op} alternatingly, one can find a chain of partial solution that are total in the limit.  The claim now follows from \Cref{chain}.
\end{proof}

n43510.content:
\begin{definition}
  We write $a \rightarrow b$ if $a\ R\ b$ holds in $A$, and say that $a$ \emph{rewrites to} (or \emph{reduces to}) $b$. We further define
  \begin{itemize}
    \item $\rightarrow^+$ as the transitive closure of $R$.
    \item $\rightarrow^*$ as the reflexive transitive closure of $R$.
    \item $\leftrightarrow^*$ as the reflexive transitive and symmetric closure of $R$.
  \end{itemize}
  We sometimes write $b\leftarrow a$, (resp. $b\ {}^*\leftarrow a$ etc) to mean $a\rightarrow b$ (resp. $a\rightarrow^*b$ etc), and chain notations, e.g. $b_1\leftarrow a\rightarrow b_2$.
\end{definition}

n43512.content:
\begin{lemma}
  If $R$ is Church-Rosser, then any normal form is \emph{unique}.
\end{lemma}

n43513.content:
\begin{theorem}
  \begin{enumerate}
    \item $R$ is Church-Rosser iff it is confluent.
    \item (Newman's lemma) if $R$ is strongly normalizing, then $R$ is confluent iff it is locally confluent.
  \end{enumerate}
\end{theorem}

n43514.content:
\begin{definition}
  Given a rewrite system $R$ and two rules $\rho_1: l_1\rightarrow r_1$ and $\rho_2: l_2\rightarrow r_2$ in $R$, we say that $(t, u)$ is a \emph{critical pair} for $\rho_1$ and $\rho_2$ if there is some non-variable position $p$ in $l_1$ such that $l_2$ unifies with the term at that position. We denote by $\sigma$ the most general unifier thus obtained and have $t = r_1\sigma$ and $u = l_1\sigma[r_2\sigma]_p$
\end{definition}

n43515.content:
\begin{theorem}
  Given a rewrite system $R$, if for every critical pair $(t, u)$ of $R$, there is a term $v$ such that $t\rightarrow^* v\ {}^*\leftarrow u$, then $R$ is locally confluent.
\end{theorem}
